begin;
create temp table fixture(actor uuid default gen_random_uuid(),viewer uuid default gen_random_uuid(),outsider uuid default gen_random_uuid(),company uuid default gen_random_uuid(),other_company uuid default gen_random_uuid(),job uuid default gen_random_uuid(),job2 uuid default gen_random_uuid(),foreignjob uuid default gen_random_uuid(),candidate uuid default gen_random_uuid(),second uuid default gen_random_uuid(),foreigncandidate uuid default gen_random_uuid(),request uuid default gen_random_uuid(),note_request uuid default gen_random_uuid());
insert into fixture default values;
grant select on fixture to authenticated,service_role;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role;
create function pg_temp.ok(name text,passed boolean) returns void language plpgsql as $$begin if passed is distinct from true then raise exception 'FAILED: %',name;end if;insert into results values(name,true);end$$;
create function pg_temp.denied(name text,statement text,expected text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate<>expected then raise exception 'FAILED wrong SQLSTATE %: % (%)',sqlstate,name,sqlerrm;end if;insert into results values(name,true);return;end;raise exception 'FAILED unexpectedly allowed: %',name;end$$;
insert into auth.users(id,email,role,aud) select id,id::text||'@collaboration-test.invalid','authenticated','authenticated' from fixture,lateral unnest(array[actor,viewer,outsider]) id;
update public.profiles set full_name='Responsável de teste' where id=(select actor from fixture);
insert into public.companies(id,name) select company,'Collaboration A' from fixture union all select other_company,'Collaboration B' from fixture;
insert into public.company_members(company_id,user_id,role) select company,actor,'owner' from fixture union all select company,viewer,'viewer' from fixture union all select other_company,outsider,'owner' from fixture;
insert into public.jobs(id,company_id,titulo,criteria) select job,company,'Analista A','[{"kind":"skill","text":"Excel","required":true,"weight":5,"min_years":null,"source":null}]'::jsonb from fixture union all select job2,company,'Analista B','[]' from fixture union all select foreignjob,other_company,'Outra empresa','[]' from fixture;
update public.jobs set descricao='Análise de planilhas e relatórios com Excel.' where id=(select job from fixture);
update public.jobs set approved_hash=private.job_hash(private.job_payload(titulo,descricao,categoria,criteria)) where id=(select job from fixture);
insert into public.candidates(id,company_id,processing_status,review_status,dados_extraidos,status,observacoes) select candidate,company,'concluido','completed','{"nome_completo":"Ana","skills":["Excel"]}'::jsonb,'aprovado','Nota geral antiga' from fixture union all select second,company,'erro','pending','{"nome_completo":"Bruna"}','novo',null from fixture union all select foreigncandidate,other_company,'concluido','completed','{}','novo',null from fixture;
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select public.set_candidate_job_link(company,candidate,job,true),public.set_candidate_job_link(company,candidate,job2,true),public.set_candidate_job_link(company,second,job,true) from fixture;
select pg_temp.ok('legacy general decision never becomes vacancy decision',(select count(*)=2 and bool_and(decision_status='novo') from public.candidate_job_links where candidate_id=(select candidate from fixture)));
select public.save_candidate_decision(company,candidate,job,0,'aprovado',true,'Experiência conferida pelo RH',request) from fixture;
select public.save_candidate_decision(company,candidate,job2,0,'rejeitado',false,'Não atende aos requisitos desta vaga',gen_random_uuid()) from fixture;
select pg_temp.ok('same person has independent decisions per vacancy',(select decision_status='aprovado' and shortlisted from public.candidate_job_links where job_id=(select job from fixture) and candidate_id=(select candidate from fixture)) and (select decision_status='rejeitado' and not shortlisted from public.candidate_job_links where job_id=(select job2 from fixture)));
select pg_temp.ok('decision has real author timestamp and justification',(select actor_id=(select actor from fixture) and actor_name='Responsável de teste' and created_at is not null and reason='Experiência conferida pelo RH' and before_status='novo' and after_status='aprovado' from public.candidate_decision_events where request_id=(select request from fixture)));
select public.save_candidate_decision(company,candidate,job,0,'aprovado',true,'Experiência conferida pelo RH',request) from fixture;
select pg_temp.ok('repeat request cannot duplicate decision event',(select count(*)=1 from public.candidate_decision_events where request_id=(select request from fixture)));
select pg_temp.denied('reused decision request cannot change its payload',$q$select public.save_candidate_decision(company,candidate,job,1,'rejeitado',true,'Experiência conferida pelo RH',request) from fixture$q$,'22023');
select pg_temp.denied('stale decision cannot overwrite another reviewer',$q$select public.save_candidate_decision(company,candidate,job,0,'rejeitado',false,'Outro parecer do RH',gen_random_uuid()) from fixture$q$,'40001');
select pg_temp.denied('empty explanation rejected',$q$select public.save_candidate_decision(company,candidate,job,1,'rejeitado',false,'',gen_random_uuid()) from fixture$q$,'22023');
select pg_temp.denied('invalid status rejected',$q$select public.save_candidate_decision(company,candidate,job,1,'invalido',false,'Uma explicação',gen_random_uuid()) from fixture$q$,'22023');
select pg_temp.denied('foreign job cannot receive a decision',$q$select public.save_candidate_decision(company,candidate,foreignjob,1,'aprovado',true,'Uma explicação',gen_random_uuid()) from fixture$q$,'42501');
select public.save_candidate_decision(company,candidate,job,1,'em_analise',false,'Retomar conferência dos requisitos',gen_random_uuid()) from fixture;
select pg_temp.ok('new decision preserves old history and updates shortlist',(select count(*)=2 from public.candidate_decision_events where job_id=(select job from fixture)) and (select decision_version=2 and not shortlisted from public.candidate_job_links where job_id=(select job from fixture) and candidate_id=(select candidate from fixture)));
select public.add_candidate_note(company,candidate,null,'Nota geral para acompanhamento',note_request) from fixture;
select public.add_candidate_note(company,candidate,job,'Nota específica da vaga A',gen_random_uuid()),public.add_candidate_note(company,candidate,job2,'Nota específica da vaga B',gen_random_uuid()) from fixture;
select public.add_candidate_note(company,candidate,null,'Nota geral para acompanhamento',note_request) from fixture;
select pg_temp.ok('notes are independent by scope with author and date',(select count(*)=3 and count(*) filter(where job_id is null)=1 and bool_and(actor_id=(select actor from fixture) and actor_name='Responsável de teste' and created_at is not null) from public.candidate_notes));
select public.add_candidate_note(company,candidate,null,'Complemento da nota geral; original preservado',gen_random_uuid()) from fixture;
select pg_temp.ok('new note never overwrites earlier text',(select count(*)=2 and bool_or(body='Nota geral para acompanhamento') from public.candidate_notes where job_id is null));
select pg_temp.denied('note idempotency key cannot silently overwrite text',$q$select public.add_candidate_note(company,candidate,null,'Texto diferente',note_request) from fixture$q$,'22023');
select pg_temp.denied('browser cannot edit or delete prior notes',$q$update public.candidate_notes set body='Sobrescrito'$q$,'42501');
select pg_temp.denied('browser cannot delete notes',$q$delete from public.candidate_notes$q$,'42501');
select pg_temp.denied('browser cannot manufacture decisions',$q$update public.candidate_job_links set decision_status='contratado'$q$,'42501');
select pg_temp.denied('browser cannot rewrite decision history',$q$update public.candidate_decision_events set reason='Alterada'$q$,'42501');
select pg_temp.denied('global note editor retired safely',$q$select public.save_candidate_review(company,candidate,0,'{"observacoes":"Substituir"}',false,false) from fixture$q$,'22023');
select pg_temp.denied('global decision editor retired safely',$q$select public.save_candidate_review(company,candidate,0,'{"status":"rejeitado"}',false,false) from fixture$q$,'22023');
select pg_temp.ok('legacy information preserved without assuming job scope',(select observacoes='Nota geral antiga' and status='aprovado' from public.candidates where id=(select candidate from fixture)));
select public.set_candidate_favorite(company,candidate,true),public.set_candidate_favorite(company,candidate,true) from fixture;
select pg_temp.ok('favorites are idempotent and searchable across company',(select count(*)=1 from public.candidate_favorites) and (select public.browse_candidates(company,'{"favorite":"mine"}')->>'filtered'='1' from fixture));
select pg_temp.ok('comparison without ranking retains both people and no fabricated run',(select r->'run'='null'::jsonb and jsonb_array_length(r->'candidates')=2 from fixture,lateral public.compare_job_candidates(company,job,array[candidate,second]) r));
select pg_temp.denied('comparison refuses cross-company candidate',$q$select public.compare_job_candidates(company,job,array[candidate,foreigncandidate]) from fixture$q$,'42501');
select pg_temp.denied('comparison requires different people',$q$select public.compare_job_candidates(company,job,array[candidate,candidate]) from fixture$q$,'22023');
reset role;
set local role service_role;
select set_config('test.collabrun',public.begin_ranking(actor,company,job,gen_random_uuid())->>'id',true) from fixture;
select public.stage_ranking(actor,current_setting('test.collabrun')::uuid,jsonb_build_array(jsonb_build_object('candidate_id',candidate,'score',80,'details','{"formula":"evidence-v3"}'::jsonb))) from fixture;
select public.finish_ranking(actor,current_setting('test.collabrun')::uuid) from fixture;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',viewer,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('authorized manager can read notes decisions and candidates',(select count(*)=4 from public.candidate_notes) and (select count(*)=3 from public.candidate_decision_events) and (select count(*)=2 from public.candidates));
select pg_temp.ok('authorized manager comparison uses one completed run',(select r->'run'->>'id'=current_setting('test.collabrun') and jsonb_array_length(r->'candidates')=2 and r->'candidates'->0->'entry'->>'run_id'=current_setting('test.collabrun') and r->'candidates'->1->'entry'->>'reason' is not null from fixture,lateral public.compare_job_candidates(company,job,array[candidate,second]) r));
select pg_temp.ok('manager cannot see another users favorites',(select count(*)=0 from public.candidate_favorites) and (select public.browse_candidates(company,'{"favorite":"mine"}')->>'filtered'='0' from fixture));
select pg_temp.denied('manager cannot change decision',$q$select public.save_candidate_decision(company,candidate,job,2,'aprovado',true,'Tentativa de alteração',gen_random_uuid()) from fixture$q$,'42501');
select pg_temp.denied('manager cannot write internal notes',$q$select public.add_candidate_note(company,candidate,null,'Tentativa de nota',gen_random_uuid()) from fixture$q$,'42501');
select public.set_candidate_favorite(company,second,true) from fixture;
select pg_temp.ok('manager can keep personal favorites without changing selection',(select count(*)=1 from public.candidate_favorites) and (select not shortlisted from public.candidate_job_links where candidate_id=(select second from fixture)));
reset role;
update public.candidates set correcoes_rh='{"localizacao":"Curitiba"}',review_version=review_version+1 where id=(select candidate from fixture);
set local role authenticated;
select pg_temp.ok('comparison flags stale analysis while preserving evaluated snapshot',(select (r->'run'->>'stale')::boolean and r->'candidates'->0->'current'->>'localizacao'='Curitiba' and r->'candidates'->0->'entry'->'snapshot'->>'localizacao' is null from fixture,lateral public.compare_job_candidates(company,job,array[candidate,second]) r));
reset role;
select set_config('request.jwt.claims',json_build_object('sub',outsider,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('other company sees no notes decisions or favorites',(select count(*)=0 from public.candidate_notes) and (select count(*)=0 from public.candidate_decision_events) and (select count(*)=0 from public.candidate_favorites));
select pg_temp.denied('other company cannot compare foreign vacancy',$q$select public.compare_job_candidates(company,job,array[candidate,second]) from fixture$q$,'42501');
select pg_temp.denied('foreign favorite cannot be added',$q$select public.set_candidate_favorite(company,candidate,true) from fixture$q$,'42501');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select public.set_candidate_job_link(company,candidate,job,false) from fixture;
select pg_temp.ok('removed relationship keeps decisions and notes readable',(select count(*)=2 from public.candidate_decision_events where job_id=(select job from fixture)) and (select count(*)=1 from public.candidate_notes where job_id=(select job from fixture)));
select pg_temp.denied('inactive link cannot receive new decision',$q$select public.save_candidate_decision(company,candidate,job,2,'aprovado',true,'Nova decisão do RH',gen_random_uuid()) from fixture$q$,'22023');
select public.set_candidate_job_link(company,candidate,job,true) from fixture;
select pg_temp.ok('reactivation preserves vacancy decision',(select decision_status='em_analise' and decision_version=2 from public.candidate_job_links where job_id=(select job from fixture) and candidate_id=(select candidate from fixture)));
select public.confirm_candidate_merge(company,candidate,second,(select review_version from public.candidates where id=candidate),(select review_version from public.candidates where id=second),'Cadastros conferidos: mesma pessoa',true) from fixture;
select pg_temp.ok('confirmed merge preserves notes and decisions in audit',(select jsonb_array_length(source_relationships->'notas')=4 and jsonb_array_length(source_relationships->'decisoes')=3 and jsonb_array_length(source_relationships->'vagas')=2 from public.candidate_merges));
reset role;
delete from public.company_members where user_id=(select viewer from fixture);
select set_config('request.jwt.claims',json_build_object('sub',viewer,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('revoked manager cannot read collaboration records',(select count(*)=0 from public.candidate_notes) and (select count(*)=0 from public.candidate_decision_events) and (select count(*)=0 from public.candidate_favorites));
select pg_temp.denied('revoked manager cannot compare even with old JWT',$q$select public.compare_job_candidates(company,job,array[candidate,second]) from fixture$q$,'42501');
reset role;
select json_build_object('passed',count(*),'tests',json_agg(name)) from results;
rollback;
